// A labelled corpus for the PII detectors.
//
// POSITIVES: { id, kind, text, value, explicit?, also? }
//   `value` is the exact substring a finding of `kind` must cover. `explicit: true` marks the formats that are unambiguous
//   (email, card, IBAN, SSN, secrets): the tests allow ZERO misses for those. `also` lists further expected values in the
//   same text, so a second hit is not counted as a false positive.
// NEGATIVES: { id, text } - ticket-style text with nothing sensitive in it; detect() must return nothing.
//
// All numbers are published test values (card test numbers, example IBANs) or made-up; none belongs to a real person.

const pos = (kind, id, text, value, extra = {}) => ({ id: `${kind}:${id}`, kind, text, value, ...extra });
const explicit = { explicit: true };

